// Modifiable lvalue examples:
int x = 10;
x = 20;                    // OK: x is modifiable lvalue

int* ptr = &x;
*ptr = 30;                 // OK: *ptr is modifiable lvalue

int& ref = x;
ref = 40;                  // OK: ref is modifiable lvalue

// Nonmodifiable lvalue examples:
const int cx = 50;
cx = 60;                   // ERROR: cx is nonmodifiable (const)

const int& cref = x;
cref = 70;                 // ERROR: cref is nonmodifiable

const char* str = "hello";
// str[0] = 'H';           // ERROR: string literal is const char[]

// Mutable members bypass const:
struct S {
    mutable int m;
};
const S s;
s.m = 100;                 // OK: mutable member modifiable in const object

// Function pointers are modifiable:
void foo();
void bar();
void (*fptr)() = foo;
fptr = bar;                // OK: function pointer is modifiable
// foo = bar;              // ERROR: functions not modifiable

code_example:
#include <iostream>
#include <string>
#include <vector>

// Example 1: Modifiable vs Nonmodifiable lvalues
void demonstrate_modifiable() {
    std::cout << "--- Modifiable Lvalues ---\n";

    int x = 10;
    x = 20;  // OK: x is modifiable lvalue
    std::cout << "Modified x: " << x << "\n";

    int* ptr = &x;
    *ptr = 30;  // OK: *ptr is modifiable lvalue
    std::cout << "Modified via ptr: " << x << "\n";

    std::cout << "\n--- Nonmodifiable Lvalues ---\n";
    const int cx = 50;
    // cx = 60;  // ERROR: nonmodifiable lvalue (const)
    std::cout << "const cx cannot be modified: " << cx << "\n";

    const int& cref = x;
    // cref = 70;  // ERROR: reference to const
    std::cout << "const reference cref: " << cref << "\n";
}

// Example 2: mutable members
class Cache {
public:
    Cache(int val) : value(val), access_count(0) {}

    int getValue() const {
        ++access_count;  // OK: mutable member modifiable in const method
        return value;
    }

    int getAccessCount() const { return access_count; }

private:
    int value;
    mutable int access_count;  // Can be modified in const objects
};

void demonstrate_mutable() {
    std::cout << "\n--- Mutable Members ---\n";

    const Cache cache(42);
    // cache.value = 100;  // ERROR: Cache is const

    std::cout << "Value: " << cache.getValue() << "\n";  // Increments access_count
    std::cout << "Value: " << cache.getValue() << "\n";  // Increments again
    std::cout << "Access count: " << cache.getAccessCount() << "\n";  // Shows 2
}

// Example 3: Class rvalues can modify
void demonstrate_rvalue_modification() {
    std::cout << "\n--- Class Rvalue Modification ---\n";

    // Temporary vector (rvalue) can call non-const member function
    std::vector<int>().push_back(5);  // OK: rvalue can modify itself
    std::cout << "Temporary vector modified (no error)\n";

    // Compare with built-in types:
    // int().operator++();  // Would be error if such syntax existed
}

// Example 4: Function pointers are modifiable
void func1() { std::cout << "func1\n"; }
void func2() { std::cout << "func2\n"; }

void demonstrate_function_pointers() {
    std::cout << "\n--- Function Pointers ---\n";

    void (*fptr)() = func1;
    fptr();  // Calls func1

    fptr = func2;  // OK: function pointer is modifiable
    fptr();  // Calls func2

    // func1 = func2;  // ERROR: functions themselves not modifiable
}

// Example 5: Incomplete type and modification
class Forward;  // Incomplete type

void demonstrate_incomplete_type() {
    std::cout << "\n--- Incomplete Type Pointer ---\n";

    Forward* ptr = nullptr;  // OK: pointer to incomplete type
    ptr = (Forward*)0x1234;  // OK: pointer itself is modifiable
    // ptr->member = 5;      // ERROR: type incomplete, cannot access members

    std::cout << "Pointer to incomplete type is modifiable\n";
}

int main() {
    std::cout << "=== Modifiable Lvalues Demo ===\n\n";

    demonstrate_modifiable();
    demonstrate_mutable();
    demonstrate_rvalue_modification();
    demonstrate_function_pointers();
    demonstrate_incomplete_type();

    return 0;
}

// Output:
// === Modifiable Lvalues Demo ===
//
// --- Modifiable Lvalues ---
// Modified x: 20
// Modified via ptr: 30
//
// --- Nonmodifiable Lvalues ---
// const cx cannot be modified: 50
// const reference cref: 30
//
// --- Mutable Members ---
// Value: 42
// Value: 42
// Access count: 2        <- mutable member modified in const object
//
// --- Class Rvalue Modification ---
// Temporary vector modified (no error)
//
// --- Function Pointers ---
// func1
// func2                  <- Function pointer reassigned
//
// --- Incomplete Type Pointer ---
// Pointer to incomplete type is modifiable
